def handle_create_user(body):
    if not isinstance(body, dict):
        return 400, {"errors": {"body": "must be an object"}}

    errors = {}

    if 'name' not in body or not isinstance(body['name'], str) or not body['name'].strip():
        errors['name'] = "required non-empty string"

    if 'age' not in body or not isinstance(body['age'], int) or body['age'] < 0 or body['age'] > 150:
        errors['age'] = "required int with 0 <= age <= 150"

    if 'email' in body:
        if not isinstance(body['email'], str) or body['email'].count('@') != 1 or not body['email'].split('@')[0] or not body['email'].split('@')[1]:
            errors['email'] = "must contain exactly one '@' with non-empty parts"

    if errors:
        return 422, {"errors": errors}

    user = {
        "name": body['name'].strip(),
        "age": body['age'],
        "email": body.get('email')
    }

    return 201, user
